/* ---------- meal prep ---------- */
const PREP=[
 {id:'teri',name:'Chicken teriyaki rice box',kcal:710,p:48,c:85,f:17,keeps:'rice',
  ing:['1 kg boneless chicken thighs','500 g rice (dry)','1 kg frozen stir-fry veg','5 tbsp soy sauce','3 tbsp honey','2 tsp garlic paste','1 tbsp cornflour'],
  steps:['Rinse and cook the rice, about 12 min. Spread it on a tray so it cools fast','Dice the chicken, fry in a hot pan 8–10 min until cooked through','Add the frozen veg, 4 min','Mix soy, honey, garlic, cornflour and 100 ml water; pour in and bubble 2 min until sticky','Split rice and chicken into 5 boxes. Lids on within an hour of cooking']},
 {id:'chilli',name:'Beef chilli rice box',kcal:700,p:45,c:90,f:13,keeps:'rice',
  ing:['750 g lean beef mince (5% fat)','500 g rice (dry)','2 tins kidney beans, drained','2 tins chopped tomatoes','1 onion, 2 peppers, 2 carrots','2 tsp each chilli powder, cumin, smoked paprika','1 beef stock cube'],
  steps:['Blend the onion, peppers and carrots into a paste: the veg disappears','Brown the mince in a big pan, 5 min','Add the veg paste and spices, 3 min','Add tomatoes, beans and stock cube; simmer 20 min until thick','Cook the rice, cool it fast, split everything into 5 boxes']},
 {id:'fajita',name:'Chicken fajita rice box',kcal:690,p:47,c:85,f:15,keeps:'rice',
  ing:['1 kg boneless chicken thighs','500 g rice (dry)','3 peppers and 2 onions, sliced','1 tin sweetcorn, drained','2 sachets fajita seasoning','1 jar salsa'],
  steps:['Cook the rice, cool it fast','Slice the chicken, toss in the seasoning, fry 8–10 min until cooked','Add peppers and onions, 5 min','Stir in the sweetcorn','Split into 5 boxes, salsa on top']},
 {id:'pesto',name:'Chicken pesto pasta box',kcal:720,p:50,c:78,f:21,keeps:'pasta',
  ing:['1 kg chicken breast or thighs','500 g pasta (dry)','Half a jar of green pesto (95 g)','500 g frozen peas and spinach','100 g grated cheddar'],
  steps:['Cook the pasta, drain, rinse under cold water','Dice and fry the chicken 8–10 min until cooked','Cook the peas and spinach 3 min, squeeze out the water','Mix pasta, chicken, veg, pesto and cheese. Half a jar of pesto is plenty: it is the most calorie-dense part','Split into 5 boxes. Tastes good cold, so no microwave needed']}
];
const KEEP={rice:'Cooked rice should be eaten within 24 hours, so: Monday\'s box goes in the fridge, the other 4 go straight in the freezer. Every night, move tomorrow\'s box to the fridge. Reheat until steaming hot, or heat it in the morning and pack it in a food flask if there\'s no microwave on site.',pasta:'Pasta keeps 3 days in the fridge: Monday to Wednesday boxes in the fridge, Thursday and Friday in the freezer. Move each one to the fridge the night before. Eat cold or reheated.'};
const STAPLES=['Oats 1 kg','Whole milk, about 12 pints','Greek yoghurt 2 kg','Eggs 15','Bread 2 loaves','Bagels 2 packs','Wraps 1 pack','Tinned tuna 4 tins','Peanut butter','Frozen berries','Cottage cheese 3 tubs','Pasta 1 kg + lean mince 750 g (dinners)','Jam or honey','Rice cakes','Electrolyte tabs'];
const monOf=s=>toS(toN(s)-(dow(s)-1));
const prepFor=s=>{const r=PREP[((Math.floor((toN(monOf(s))-toN('2026-11-23'))/7)%4)+4)%4];if(!CFG||!CFG.diet)return r;const sw=diet(CFG.diet),walk=v=>typeof v==='string'?sw(v):Array.isArray(v)?v.map(walk):v&&typeof v==='object'?Object.fromEntries(Object.entries(v).map(([k,x])=>[k,k==='id'||k==='keeps'?x:walk(x)])):v;return walk(r)};
function fuel2(p,s){const f=fuel(p),r=prepFor(s);f.meals=f.meals.map(m=>m[0]==='13:00'?['13:00','Prep box: '+r.name,r.kcal]:m);return f}

/* ---------- small helpers ---------- */
const COL={g:'var(--go)',a:'var(--amb)',r:'var(--red)',n:'var(--mut)'};
function ring(val,max,color,label,big,sub,href){const r=42,C=2*Math.PI*r,f=val>0?Math.min(1,val/max):0;return '<a class="dial" href="'+href+'"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="'+r+'" class="trk"/><circle cx="50" cy="50" r="'+r+'" stroke="'+color+'" stroke-dasharray="'+(C*f).toFixed(1)+' '+C.toFixed(1)+'" class="val"/></svg><div class="dv"><b>'+big+'</b><span>'+sub+'</span></div><div class="dl">'+label+'</div></a>'}
const pill=t=>t?'<span class="pill '+t+'">'+({EASY:'Easy',MOD:'Moderate',HARD:'Hard',KEY:'Key'}[t])+'</span>':'';
function nextRace(s){const n=toN(s);for(const [r,name] of RACES)if(toN(r)>=n)return [r,name,toN(r)-n];return null}
function timeline(){
  const a=toN(START),b=toN(END),T=b-a,pos=n=>((n-a)/T*100).toFixed(2)+'%';
  const C={'Build':'#8f949b','Deload':'#4a4e55','Strength + power':'var(--acc)','Taper':'#8f949b','Race season':'var(--ink)','Rest':'#4a4e55','Off-season':'#6b7078'};
  return '<div class="tl" role="img" aria-label="Season timeline">'+PH.map(p=>'<span style="left:'+pos(toN(p[0]))+';width:'+((toN(p[1])-toN(p[0])+1)/T*100).toFixed(2)+'%;background:'+C[p[2]]+'"></span>').join('')+RACES.map(r=>'<i style="left:'+pos(toN(r[0]))+'"></i>').join('')+'<b style="left:'+pos(Math.min(Math.max(toN(S.date),a),b))+'"></b></div><div class="tll"><span>Build</span><span style="color:var(--acc)">Strength + power</span><span>Taper</span><span style="color:var(--ink)">Race season</span><span>Off-season</span></div>';
}

/* ---------- top ---------- */
const NAVI={today:'<path d="M3 11.5 12 4l9 7.5V20a1 1 0 0 1-1 1h-5v-6h-6v6H4a1 1 0 0 1-1-1z"/>',week:'<rect x="3.5" y="5" width="17" height="15.5" rx="2.5"/><path d="M3.5 10h17M8 3v4M16 3v4"/>',food:'<path d="M7 3v8a2 2 0 0 0 2 2v8M5 3v5a2 2 0 0 0 2 2M9 3v5M17 21V3c-2 0-3.5 2.5-3.5 6s1.5 4 3.5 4"/>',track:'<path d="M5 21V4m0 0h11l-2 4 2 4H5"/>',stats:'<path d="M4 20V10m6 10V4m6 16v-7m4 7H3"/>'};
const navIc=k=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+NAVI[k]+'</svg>';

const avInner=()=>{const p=S.prof||{};return p.photo&&/^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(p.photo)?'<img src="'+p.photo+'" alt="">':esc(((p.name||(p.legacy?'Kayden':'R')).trim()||'R')[0].toUpperCase())};
function profCard(){const p=S.prof||{};return '<div class="card" style="max-width:760px"><span class="lab">YOUR PROFILE</span><div class="pc"><div class="av big" aria-hidden="true">'+avInner()+'</div><div class="pcf"><div class="fields">'+fld('profile/main','name','Name',{text:true,ph:'Your name'})+'</div>'+(p.cfg?'<button type="button" class="ghost" id="obEdit" style="margin-top:10px">Edit race dates, goal and week</button>':'')+'<div class="row2" style="flex-wrap:wrap;margin-top:10px"><label class="filebtn" for="avfile" style="margin-top:0">'+(p.photo?'Change photo':'Add photo')+'</label>'+(p.photo?'<button class="ghost" id="avdel">Remove photo</button>':'')+'</div><input id="avfile" class="vh" type="file" accept="image/*">'+(S.avMsg?'<p style="color:var(--amb);font-weight:600;margin:8px 0 0">'+esc(S.avMsg)+'</p>':'')+'</div></div></div>'}
document.addEventListener('change',async e=>{const t=e.target;if(!t||t.id!=='avfile'||!t.files||!t.files[0])return;const f=t.files[0];t.value='';t.blur();
  if(!/^image\//.test(f.type||'image/')){S.avMsg='Choose a photo file.';render();return}
  S.avMsg='Saving photo…';render();
  try{const b=await createImageBitmap(f),s=Math.min(b.width,b.height),sx=(b.width-s)/2,sy=(b.height-s)/2,cv=document.createElement('canvas');cv.width=cv.height=320;
    cv.getContext('2d').drawImage(b,sx,sy,s,s,0,0,320,320);S.prof.photo=cv.toDataURL('image/jpeg',0.82);save('profile/main');S.avMsg=''}
  catch(err){S.avMsg='That photo couldn\'t be read. Try a JPEG or PNG.'}
  render()});
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('#avdel');if(!t)return;delete S.prof.photo;save('profile/main');render()});
function renderBoard(){
  const p=plan(S.date),nr=nextRace(S.date),isT=S.date===todayS(),name=(S.prof&&S.prof.name)||(S.prof&&S.prof.legacy?'Kayden':'Rider'),h=new Date().getHours();
  const hi=h<12?'Morning':h<18?'Afternoon':'Evening';
  const mon=toN(S.date)-(dow(S.date)-1),races=new Set((typeof RACES!=='undefined'?RACES:[]).map(r=>r[0]));
  const strip='<div class="ds"><button class="wk" id="wprev" aria-label="Previous week">‹</button>'+[0,1,2,3,4,5,6].map(i=>{const s=toS(mon+i),pp=plan(s),key=(pp.am&&pp.am.tier==='KEY')||(pp.pm&&pp.pm.tier==='KEY');return '<button class="d'+(s===S.date?' on':'')+(s===todayS()?' td':'')+'" data-dstrip="'+s+'" aria-label="'+esc(nice(s))+'">'+DN[dow(s)]+'<b>'+(+s.slice(8,10))+'</b><i class="'+(races.has(s)?'r':key?'k':'')+'"></i></button>'}).join('')+'<button class="wk" id="wnext" aria-label="Next week">›</button></div>';
  const showStrip=S.view!=='track'&&S.view!=='stats';
  $('#board').innerHTML='<div class="uh"><div class="who"><a class="av" href="#stats" data-ss="profile" aria-label="Your profile">'+avInner()+'</a><div><b>'+hi+', '+esc(name)+'</b><small>'+esc(p.c.label)+'</small></div></div><div class="act">'+(nr?'<span class="rp" title="'+esc(nr[1])+'"><b>'+(nr[2]===0?'Race day':nr[2]+' days')+'</b><span class="rn"> to '+esc(nr[1])+'</span></span>':'')+'<a class="ib" href="#stats" data-ss="profile" aria-label="Settings and profile"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.8l.1.1a2 2 0 1 1-2.8 2.8l-.1-.1a1.7 1.7 0 0 0-1.8-.3 1.7 1.7 0 0 0-1 1.5V21a2 2 0 1 1-4 0v-.1a1.7 1.7 0 0 0-1.1-1.5 1.7 1.7 0 0 0-1.8.3l-.1.1a2 2 0 1 1-2.8-2.8l.1-.1a1.7 1.7 0 0 0 .3-1.8 1.7 1.7 0 0 0-1.5-1H3a2 2 0 1 1 0-4h.1a1.7 1.7 0 0 0 1.5-1.1 1.7 1.7 0 0 0-.3-1.8l-.1-.1a2 2 0 1 1 2.8-2.8l.1.1a1.7 1.7 0 0 0 1.8.3H9a1.7 1.7 0 0 0 1-1.5V3a2 2 0 1 1 4 0v.1a1.7 1.7 0 0 0 1 1.5 1.7 1.7 0 0 0 1.8-.3l.1-.1a2 2 0 1 1 2.8 2.8l-.1.1a1.7 1.7 0 0 0-.3 1.8V9a1.7 1.7 0 0 0 1.5 1H21a2 2 0 1 1 0 4h-.1a1.7 1.7 0 0 0-1.5 1z"/></svg></a></div></div>'
   +(showStrip?strip:'')
   +'<nav class="tabs">'+[['today','Today'],['week','Plan'],['food','Food'],['track','Track'],['stats','Stats']].map(v=>'<a href="#'+v[0]+'" class="'+(S.view===v[0]?'on':'')+'" aria-label="'+v[1]+'" title="'+v[1]+'">'+navIc(v[0])+'<span>'+v[1]+'</span></a>').join('')+'</nav>';
}
document.addEventListener('click',e=>{const t=e.target.closest&&e.target.closest('[data-dstrip]');if(!t)return;S.date=t.dataset.dstrip;S.keepOpen=false;S.wo=null;S.orig=false;render()});

/* ---------- today ---------- */
function sessBody(sess,s){
  const doc='days/'+s,dd=docObj(doc);
  const nsets=(sess.ex||[]).reduce((a,x)=>a+(x.rounds?0:x.sets),0);
  const eqk=sess.eq||equip(sess.kind,dow(s)),eqn=eqk&&EQ[eqk]?EQ[eqk][0]:(sess.ex?'Gym floor':'');
  let h='<div class="stats"><span><b>'+esc(sess.mins)+'</b> min</span>'+(eqn?'<span>Equipment: <b>'+esc(eqn)+'</b></span>':'')+(nsets?'<span><b>'+nsets+'</b> working sets</span>':'')+(sess.hr?'<span><b>'+esc(sess.hr)+'</b></span>':'')+'</div>';
  if(eqk&&EQ[eqk]&&eqk!=='mixed')h+='<p class="mut" style="margin:0 0 6px"><b style="color:var(--ink)">Settings:</b> '+esc(EQ[eqk][1])+'. <b style="color:var(--ink)">Machine taken?</b> '+esc(SWAP[eqk])+'</p>';
  if(sess.ex)h+='<p class="mut" style="margin:0 0 6px"><b style="color:var(--ink)">Machines:</b> rower for the warm-up, Wattbike or spin bike for the add-on and cool-down'+(sess.ex.some(x=>x.id==='fin_a')?', air bike for the finisher':'')+'.</p>';
  if(sess.why)h+='<p class="mut" style="margin:0 0 6px">'+esc(sess.why)+'</p>';
  if(sess.amber)h+='<div class="call a" style="margin:8px 0"><i></i><span>Amber: one fewer hard effort, stay at the bottom of the heart-rate range.</span></div>';
  h+=clHTML(sess,s,allRows(sess));
  if(sess.tests)h+='<div class="ex"><b>Log your results</b><div class="fields" style="margin-top:6px">'+sess.tests.map(t=>fld('profile/main','bench.'+t[0]+'.wk1',t[1])).join('')+'</div></div>';
  (sess.ex||[]).forEach(x=>{
    const key=sess.id+':'+x.id,last=x.rounds?null:lastFor(x.id,s);
    let lt='';if(last){lt='<div class="last'+(last.allDone?' up':'')+'">Last: '+esc(last.kg)+' kg × '+esc(last.reps)+' ('+esc(nice(last.d))+')'+(last.allDone?(typeof x.load==='object'?' · all sets done: add 2.5 kg':' · all sets done: go heavier'):'')+'</div>'}
    h+='<div class="ex'+(x.fin?' fin':'')+'"><div class="exh"><b>'+esc(x.name)+'</b><span class="rx">'+esc(x.sets)+(x.rounds?(x.unit==='min'?' min':' rounds'):' × '+esc(x.reps))+'</span></div><div class="cue">'+(x.rounds?'<span class="load">'+esc(x.reps)+'</span><br>':'')+'<span class="load">'+esc(loadTxt(x.load))+'</span> · rest '+esc(x.rest)+' · '+esc(x.cue)+'</div>'+lt+(isFocus()&&!x.rounds?'<button class="ghost" data-ql="'+esc(sess.id)+'|'+esc(x.id)+'" style="min-height:36px;padding:6px 12px;margin-top:4px">✓ All sets as planned</button>':'')+'<div class="sets">';
    for(let i=0;i<x.sets;i++)h+=x.rounds?'<div class="set r"><i>'+(x.unit==='min'?'Min ':'Round ')+(i+1)+'</i>'+chk(doc,'sets.'+key+'.'+i+'.done',x.name+' '+(i+1))+'</div>':'<div class="set"><i>'+(i+1)+'</i>'+inp(doc,'sets.'+key+'.'+i+'.kg',{ph:'kg',lab:x.name+' set '+(i+1)+' kg'})+inp(doc,'sets.'+key+'.'+i+'.reps',{ph:'reps',lab:x.name+' set '+(i+1)+' reps'})+chk(doc,'sets.'+key+'.'+i+'.done',x.name+' set '+(i+1)+' done')+'</div>';
    h+='</div></div>';
  });
  const PF=isFocus()?[['avg','Avg HR'],['rpe','Effort 1–10']].concat(sess.drop?[['hrEnd','HR at finish'],['hr60','HR 60 s later']]:[]):[['dur','Duration (min)'],['avg','Avg HR'],['max','Max HR'],['z45','Mins in zones 4–5']].concat(sess.drop?[['hrEnd','HR at finish'],['hr60','HR 60 s later']]:[]).concat([['rpe','Effort 1–10']]);
  h+='<div class="ex"><b>Polar + how it went</b><div class="fields" style="margin-top:6px">'+PF.map(f=>fld(doc,'polar.'+sess.id+'.'+f[0],f[1])).join('')+'</div>'+(isFocus()?'<details style="margin-top:6px"><summary class="mut" style="cursor:pointer">More Polar numbers</summary><div class="fields" style="margin-top:6px">'+[['dur','Duration (min)'],['max','Max HR'],['z45','Mins in zones 4–5']].map(f=>fld(doc,'polar.'+sess.id+'.'+f[0],f[1])).join('')+'</div></details>':'');
  const pe=getK(dd,'polar.'+sess.id)||{};if(+pe.hrEnd>0&&+pe.hr60>0)h+='<p class="mut">HR drop in 60 s: <b style="color:var(--ink)">'+(pe.hrEnd-pe.hr60)+' bpm</b></p>';
  h+='<div class="chk" style="border:0">'+chk(doc,'done.'+sess.id,'Session done')+'<span><b>Mark session done</b></span><small></small></div></div>';
  return h;
}
function item(id,time,title,sub,tier,done,body,open){return '<details class="item" id="it-'+id+'"'+(open?' open':'')+'><summary><span class="tm">'+esc(time)+'</span><span class="it"><b>'+esc(title)+'</b><span>'+esc(sub)+'</span></span>'+(done?'<span class="pill done">Done</span>':pill(tier))+'</summary><div class="body">'+body+'</div></details>'}
function planBlocks(list){return list.map((x,i)=>'<div class="sess'+(/moto|hot lap|baseline/i.test(x.title)?' k':'')+'"><span class="lab">Session '+(i+1)+(x.mins?' · '+esc(x.mins)+' min':'')+'</span><h3>'+esc(x.title)+'</h3><div>'+esc(x.focus||'')+'</div>'+(x.items&&x.items.length?'<ul class="steps">'+x.items.map(y=>'<li>'+esc(y)+'</li>').join('')+'</ul>':'')+'</div>').join('')}
function trackItem(p,s){
  const ex=tdays().filter(t=>t.date===s);
  if(ex.length){const t=ex[0];return item('trk','Track',t.track||'Track day',(TT[t.type]||'')+' · '+(t.sessions||4)+' × '+(t.len||20)+' min',p.track.tier,false,'<p class="mut">Session plans, lap log and bike setup are on the track day page.</p><button data-go="'+esc(t.id)+'">Open track day</button>',false)}
  return item('trk','Track','Track day · 4 sessions','Focus: '+focusFor(s),p.track.tier,false,'<p class="mut">Generic plan. Message Claude the track, the ground and the session length for a tailored one with a lap log.</p>'+planBlocks(trackPlan(p.track.kind,s,'mixed',4,20))+'<div class="row2"><button data-new="'+esc(s)+'">Set up this track day</button></div>',false);
}
function renderToday(){
  const s=S.date,p=plan(s),doc='days/'+s,d=docObj(doc),prev=S.days[toS(toN(s)-1)],v=verdict(d,prev);
  const w=d.whoop||{},rec=+w.rec,sl=sleepH(w.sleep),st=+w.strain,L=dayLoad(p);
  const dials='<div class="dials">'+ring(rec,100,COL[v[0]],'RECOVERY',rec>0?rec+'%':'—',rec>0?'':'tap to log','#log')+ring(sl,8,'var(--sleep)','SLEEP',sl>0?fmtH(sl):'—',sl>0?'of 8 h':'tap to log','#log')+ring(st>0?st:L.a/12*21,21,'var(--blue)','STRAIN',st>0?st.toFixed(1):(L.k?'Key':L.a>=4?'High':L.a>=2?'Med':'Low'),st>0?'logged':'planned','#log')+'</div>';
  const call='<div class="call '+v[0]+'"><i></i><span>'+esc(v[1])+'</span></div>';
  let list='';
  if(!p.am&&!p.pm&&!p.track)list='<div class="card"><h3>Rest day</h3><p class="mut" style="margin:4px 0 0">'+esc(p.title)+'. Walk, stretch, eat well and sleep.</p></div>';
  const dn=d.done||{};
  if(p.am)list+=item('am',p.am.time,p.am.title,(p.am.mins||'')+' min'+(p.am.hr?' · '+p.am.hr:''),p.am.tier,dn.am,sessBody(p.am,s),false);
  if(p.pm)list+=item('pm',p.pm.time,p.pm.title,(p.pm.mins||'')+' min'+(p.pm.ex?' · '+p.pm.ex.length+' exercises':''),p.pm.tier,dn.pm,sessBody(p.pm,s),false);
  if(p.track)list+=trackItem(p,s);
  const f=fuel2(p,s);const eaten=f.meals.reduce((a,m,i)=>a+(getK(d,'meals.'+i)?m[2]:0),0);
  const fuelC='<div class="card"><span class="lab">FUEL · '+esc({gym:'TRAINING DAY',rec:'RECOVERY DAY',track:'TRACK DAY',race:'RACE DAY'}[p.type])+(f.cut?' · LEAN-DOWN':'')+'</span><div style="display:flex;justify-content:space-between;align-items:end;gap:10px"><div><span class="kc">'+eaten+'</span><span class="mut"> / '+f.kcal+' kcal</span></div><a href="#food" class="mut">Meal prep ›</a></div><div class="bars">'+[['Protein',f.p,'g','var(--go)',+d.protein],['Carbs',f.c,'g','var(--blue)',null],['Fat',f.f,'g','var(--amb)',null],['Water',f.water,'L','var(--sleep)',+d.water]].map(b=>'<div class="br"><span>'+b[0]+'</span><div class="t"><span style="width:'+(b[4]>0?Math.min(100,b[4]/b[1]*100):0)+'%;background:'+b[3]+'"></span></div><span class="mut">'+(b[4]>0?b[4]+' / ':'')+b[1]+' '+b[2]+'</span></div>').join('')+'</div>'+f.meals.map((m,i)=>'<div class="chk">'+chk(doc,'meals.'+i,m[1])+'<span><b>'+esc(m[0])+'</b> '+esc(m[1])+'</span><small>'+(m[2]?m[2]+' kcal':'')+'</small></div>').join('')+'<div class="fields" style="margin-top:10px">'+fld(doc,'water','Water (L)')+fld(doc,'protein','Protein eaten (g)')+'</div><div class="chk">'+chk(doc,'supp.creatine','Creatine')+'<span>Creatine 5 g</span><small></small></div>'+(['10','11','12','01','02','03'].includes(s.slice(5,7))?'<div class="chk">'+chk(doc,'supp.vitd','Vitamin D')+'<span>Vitamin D 10 micrograms</span><small></small></div>':'')+'</div>';
  const logC='<details class="item" id="log"'+(rec>0?'':' open')+'><summary><span class="tm">AM</span><span class="it"><b>Morning check-in</b><span>Whoop numbers and weight</span></span>'+(rec>0?'<span class="pill done">Logged</span>':'<span class="pill">To do</span>')+'</summary><div class="body"><div class="fields" style="margin-top:12px">'+[['rec','Recovery %'],['hrv','HRV (ms)'],['rhr','Resting HR'],['sleep','Sleep (e.g. 7:50)'],['sleepPerf','Sleep perf. %'],['strain','Strain (yesterday)']].map(x=>fld(doc,'whoop.'+x[0],x[1])).join('')+fld(doc,'weight','Weight (kg)')+(dow(s)===1?fld(doc,'waist','Waist (cm), Mondays'):'')+'</div></div></details>';
  const notes='<div class="card"><span class="lab">NOTES</span><textarea data-doc="'+esc(doc)+'" data-k="notes" id="notes" rows="3" aria-label="Notes" placeholder="How did today feel? Pain, arm pump, wins?">'+esc(d.notes||'')+'</textarea></div>';
  return dials+'<div class="grid"><div>'+call+logC+list+notes+'<p class="mut">Classic layout. <a href="#today" id="lay">Switch to Focus</a></p></div><div>'+fuelC+'</div></div>';
}

/* ---------- plan (week) ---------- */
function renderWeek(){
  const n=toN(S.date),mon=n-(dow(S.date)-1);let key=0,tot=0,dn=0,h='';
  for(let i=0;i<7;i++){const s=toS(mon+i),p=plan(s),d=S.days[s]||{},L=dayLoad(p);
    for(const x of [p.am,p.pm,p.track])if(x&&x.tier==='KEY')key++;
    const t=(p.am?1:0)+(p.pm?1:0),dd=(d.done&&d.done.am?1:0)+(d.done&&d.done.pm?1:0);tot+=t;dn+=dd;
    const lines=[p.am&&(p.am.time+' '+p.am.title),p.pm&&(p.pm.time+' '+p.pm.title),p.track&&p.title,(!p.am&&!p.pm&&!p.track)&&p.title].filter(Boolean);
    h+='<a href="#today" class="wd'+(s===S.date?' on':'')+'" data-day="'+s+'"><span><b>'+esc(DN[dow(s)])+'</b><small>'+esc((+s.slice(8,10))+' '+MN.at(+s.slice(5,7)-1))+'</small></span><small>'+lines.map(esc).join('<br>')+'</small><span><div class="t"><span class="'+(L.k?'k':'')+'" style="width:'+Math.max(6,Math.min(100,L.a/8*100))+'%"></span></div><small style="text-align:right;margin-top:4px">'+(t?dd+'/'+t:'')+'</small></span></a>'}
  const sc=weekScore(mon);const score=isFocus()&&sc.days?'<div class="dials">'+ring(sc.pl?sc.dn/sc.pl*100:0,100,'var(--go)','SESSIONS',sc.dn+'/'+sc.pl,'done','#week')+ring(sc.ci/sc.days*100,100,'var(--blue)','CHECK-INS',sc.ci+'/'+sc.days,'logged','#week')+ring(sc.sl/sc.days*100,100,'var(--sleep)','8 H SLEEP',sc.sl+'/'+sc.days,'nights','#week')+'</div>':'';
  let eqrows='';for(let i=0;i<7;i++){const s=toS(mon+i),p=plan(s);for(const k of ['am','pm']){const x=p[k];if(!x)continue;const e=x.eq&&EQ[x.eq];eqrows+='<tr><td>'+esc(DN[dow(s)]+' '+k.toUpperCase())+'</td><td>'+esc(x.title)+'</td><td><b>'+esc(e?e[0]:(x.ex?'Gym floor + rower warm-up':'Mat'))+'</b>'+(e&&x.eq!=='mixed'?'<div class="mut" style="font-size:12px">'+esc(e[1])+(WHY[x.eq]?' · '+esc(WHY[x.eq]):'')+'</div>':'')+'</td></tr>'}}
  const eqC='<div class="card"><span class="lab">MACHINES THIS WEEK</span><div class="scroll"><table><thead><tr><th>Day</th><th>Session</th><th>Machine</th></tr></thead><tbody>'+eqrows+'</tbody></table></div><p class="mut" style="margin-bottom:0">Machine taken? Air bike or treadmill → Wattbike. Rower → SkiErg, damper 5. Wattbike → rower at 18–22 strokes a minute. Keep the same heart-rate target.</p></div>';
  return score+'<div class="card"><span class="lab">SEASON</span><h2>'+esc(ctx(toS(mon)).label)+'</h2>'+timeline()+'</div><div class="card" style="display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center"><div><span class="lab">WEEK OF '+esc(nice(toS(mon)).toUpperCase())+'</span><div class="stats" style="margin:0"><span><b>'+key+'</b> key sessions</span><span><b>'+dn+'/'+tot+'</b> done</span></div></div><div class="row2" style="margin:0"><button id="wprev" class="ghost" aria-label="Previous week">‹ Week</button><button id="wnext" class="ghost" aria-label="Next week">Week ›</button></div></div><div class="wk">'+h+'</div><p class="mut">Bar = planned load. Yellow = includes a key session.</p>'+eqC;
}

/* ---------- food ---------- */
function renderFood(){
  const mon=monOf(S.date),r=prepFor(S.date),doc='days/'+mon,nxt=prepFor(toS(toN(mon)+7));
  const tasks=['Shop on Saturday or Sunday (list below)','Sunday evening: cook the lunch batch, about 60 min','Store it: '+(r.keeps==='rice'?'Monday in the fridge, 4 in the freezer':'Mon–Wed in the fridge, Thu–Fri in the freezer'),'Boil 6 eggs and mix 2 tins of tuna with a little mayo and sweetcorn for the 10:00 wraps','Make tomorrow\'s overnight oats every night (2 minutes)','Every night: move tomorrow\'s lunch box from the freezer to the fridge'];
  return '<div class="grid"><div><div class="card rec"><span class="lab">THIS WEEK\'S LUNCH · 5 BOXES · MON–FRI</span><h2>'+esc(r.name)+'</h2><div class="stats"><span><b>'+r.kcal+'</b> kcal</span><span><b>'+r.p+'g</b> protein</span><span><b>'+r.c+'g</b> carbs</span><span><b>'+r.f+'g</b> fat</span><span>per box</span></div><div class="ex"><b>Ingredients (makes 5)</b><ul class="ing">'+r.ing.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div><div class="ex"><b>Method</b><ol class="steps">'+r.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></div><div class="ex"><b>Storing it safely</b><p style="margin:4px 0 0">'+esc(KEEP[r.keeps])+'</p></div></div><div class="card"><span class="lab">ROTATION</span><p style="margin:0">4 lunches rotate every week so you never get bored. Next week: <b>'+esc(nxt.name)+'</b>.</p></div></div><div><div class="card"><span class="lab">PREP CHECKLIST · WEEK OF '+esc(nice(mon).toUpperCase())+'</span>'+tasks.map((t,i)=>'<div class="chk">'+chk(doc,'prep.'+i,t)+'<span>'+esc(t)+'</span><small></small></div>').join('')+'</div><div class="card"><span class="lab">SHOPPING LIST · ABOUT £45–50 AT ALDI OR LIDL</span>'+r.ing.concat(STAPLES).map((t,i)=>'<div class="chk">'+chk(doc,'shop.'+i,t)+'<span>'+esc(t)+'</span><small></small></div>').join('')+'</div></div></div>';
}

/* ---------- track ---------- */
function setupForm(doc,base){return '<div class="fields">'+SETF.map(f=>fld(doc,base+f[0],f[1],{text:/tyre\.(front|rear)|bike\./.test(f[0])})).join('')+'</div>'}
function trackDays(){
  const list=tdays().sort((a,b)=>b.date.localeCompare(a.date));
  const cur=S.trk&&S.track[S.trk]?{id:S.trk,...S.track[S.trk]}:null;
  let h='';
  if(cur){
    const doc='track/'+cur.id,sess=cur.plan&&cur.plan.length?cur.plan.map(x=>({title:x.title||'',focus:x.focus||'',items:x.items||[],mins:x.mins||cur.len})):trackPlan((plan(cur.date).track||{kind:'sat'}).kind,cur.date,cur.type,cur.sessions,cur.len);
    const tk=cur.trackId&&S.tracks[cur.trackId];
    h+='<div class="card"><span class="lab">'+esc(nice(cur.date).toUpperCase())+' · '+esc((TT[cur.type]||'Mixed').toUpperCase())+' · '+esc(sess.length)+' × '+esc(cur.len||20)+' MIN</span><div style="display:flex;justify-content:space-between;gap:10px;align-items:center;flex-wrap:wrap"><h2 style="font-size:26px">'+esc(cur.track||'Track day')+'</h2>'+(tk?'<a href="#track" data-tk="'+esc(cur.trackId)+'" class="pill" style="text-decoration:none">Track page ›</a>':'')+'</div><p class="mut">'+esc(TIP[cur.type]||TIP.mixed)+'</p>'+(cur.coach?'<div class="ex"><b>Coach brief</b><p class="note" style="margin:4px 0 0">'+esc(cur.coach)+'</p></div>':'')+(cur.between&&cur.between.length?'<div class="ex"><b>Between every session</b><ul class="steps">'+cur.between.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':'')+'</div>';
    sess.forEach((x,i)=>{const k='log.'+i;const lg=getK(docObj(doc),k)||{};const gap=+lg.best>0&&+lg.last2>0?(lg.last2-lg.best).toFixed(1):'';
      const body='<p style="margin:12px 0 6px">'+esc(x.focus)+'</p>'+(x.items&&x.items.length?'<ol class="steps">'+x.items.map(y=>'<li>'+esc(y)+'</li>').join('')+'</ol>':'')+'<div class="ex"><b>Log</b><div class="fields" style="margin-top:6px">'+[['laps','Laps'],['best','Best lap (m:ss.s)',1],['avg','Avg lap',1],['last2','Last 2 laps avg',1],['sec','Corner sector best',1],['sg','Good starts'],['st','Total starts'],['hrA','Polar avg HR'],['hrM','Polar max HR'],['pump','Arm pump 0–10']].map(f=>fld(doc,k+'.'+f[0],f[1],{time:f[2]})).join('')+'</div>'+(gap?'<p class="mut">Gap best → last 2 laps: <b style="color:var(--ink)">'+gap+' s</b>'+(+gap<=2?' · on target':' · target is under 2 s')+'</p>':'')+'<input data-doc="'+esc(doc)+'" data-k="'+esc(k)+'.notes" id="'+esc(fid(doc,k+'n'))+'" placeholder="What worked, what didn\'t" value="'+esc(lg.notes||'')+'" style="margin-top:6px" aria-label="Session '+(i+1)+' notes"></div>';
      h+=item('ts'+i,'S'+(i+1),x.title,(x.mins?x.mins+' min':'')+(+lg.best>0?' · best '+fmtT(lg.best):''),/moto|hot lap|baseline/i.test(x.title)?'KEY':'MOD',+lg.best>0,body,i===0)});
    h+='<div class="card"><span class="lab">BIKE SETUP USED TODAY</span>'+(cur.setupTips&&cur.setupTips.length?'<div class="ex"><b>Starting points</b><ul class="steps">'+cur.setupTips.map(y=>'<li>'+esc(y)+'</li>').join('')+'</ul></div>':'')+setupForm(doc,'setup.')+'<div class="fields" style="margin-top:8px">'+fld(doc,'cond','Conditions',{text:true})+fld(doc,'rating','Setup worked? 1–5')+'</div><div class="row2">'+(cur.trackId?'<button id="savebase" data-id="'+esc(cur.id)+'">Save as base setup</button>':'')+'<button class="'+(S.del===cur.id?'warn':'ghost')+'" id="deltd" data-id="'+esc(cur.id)+'">'+(S.del===cur.id?'Tap again to delete':'Delete track day')+'</button></div></div>';
  }
  const opts=Object.entries(S.tracks).filter(([k,t])=>t&&t.name).sort((a,b)=>a[1].name.localeCompare(b[1].name));
  const side='<div class="card"><span class="lab">TRACK DAYS</span>'+(list.length?list.map(t=>{const b=bestOf(t);return '<div class="chk" style="grid-template-columns:minmax(0,1fr) auto"><a href="#track" data-go="'+esc(t.id)+'"><b>'+esc(nice(t.date))+'</b> · '+esc(t.track||'Track')+'</a><small>'+(b?'best '+fmtT(b):esc(TT[t.type]||''))+'</small></div>'}).join(''):'<p class="empty">No track days yet.</p>')+'</div><div class="card"><span class="lab">NEW TRACK DAY</span><p class="mut" style="margin-top:0">Or message Claude the track, the ground, how many sessions and how long.</p><div class="fields"><div><label for="nt-date">Date</label><input id="nt-date" type="date" value="'+esc(S.newDate||S.date)+'"></div><div><label for="nt-trk">Track</label><select id="nt-trk"><option value="">+ New track</option>'+opts.map(([k,t])=>'<option value="'+esc(k)+'">'+esc(t.name)+'</option>').join('')+'</select></div><div><label for="nt-name">New track name</label><input id="nt-name" placeholder="Track name"></div><div><label for="nt-type">Ground</label><select id="nt-type">'+Object.entries(TT).map(([k,v])=>'<option value="'+k+'">'+v+'</option>').join('')+'</select></div><div><label for="nt-n">Sessions</label><input id="nt-n" inputmode="numeric" value="4"></div><div><label for="nt-len">Mins each</label><input id="nt-len" inputmode="numeric" value="20"></div></div><div class="row2"><button id="nt-add">Create plan + log</button></div></div>';
  return cur?'<div class="grid"><div>'+h+'</div><div>'+side+'</div></div>':side;
}
function trackLib(){
  const tk=S.tk&&S.tracks[S.tk]?S.tk:null;
  if(!tk){const all=Object.entries(S.tracks).filter(([k,t])=>t&&t.name).sort((a,b)=>a[1].name.localeCompare(b[1].name));
    return '<p class="mut" style="margin-top:0">Each track keeps its base setup, gearing, tyre pressures and every visit\'s lap times. Tracks are added when you create a track day.</p>'+(all.length?'<div class="tlist">'+all.map(([k,t])=>{const v=tdays().filter(d=>d.trackId===k);const b=Math.min(...v.map(bestOf).filter(x=>x));return '<a class="tcard" href="#track" data-tk="'+esc(k)+'"><span class="lab">'+esc((TT[t.ground]||'').toUpperCase())+(t.location?' · '+esc(t.location.toUpperCase()):'')+'</span><b>'+esc(t.name)+'</b><span class="mut">'+v.length+' visit'+(v.length===1?'':'s')+(isFinite(b)?' · best '+fmtT(b):'')+'</span><br><span class="mut" style="font-size:13px">'+esc(setupSum(t.setup)||'No base setup saved yet')+'</span></a>'}).join('')+'</div>':'<p class="empty">No tracks yet.</p>');}
  const t=S.tracks[tk],doc='tracks/'+tk,v=tdays().filter(d=>d.trackId===tk).sort((a,b)=>b.date.localeCompare(a.date));
  const pts=v.filter(bestOf).map(d=>[toN(d.date),bestOf(d)]).sort((a,b)=>a[0]-b[0]);const b=pts.length?Math.min(...pts.map(x=>x[1])):null;
  return '<div class="row2" style="margin:0 0 12px"><a href="#track" data-tk="" class="pill" style="text-decoration:none">‹ All tracks</a></div><div class="grid"><div><div class="card"><span class="lab">'+esc((TT[t.ground]||'').toUpperCase())+' · '+v.length+' VISITS</span><div style="display:flex;justify-content:space-between;gap:10px;align-items:end;flex-wrap:wrap"><h2 style="font-size:30px">'+esc(t.name)+'</h2><div style="text-align:right"><span class="lab">BEST LAP</span><span class="big">'+(b?fmtT(b):'—')+'</span></div></div><p class="mut">'+esc(TIP[t.ground]||TIP.mixed)+'</p><div class="fields">'+fld(doc,'location','Location',{text:true})+'</div></div><div class="card"><span class="lab">BEST LAP PER VISIT</span>'+lineChart('c4',pts,'s')+'</div><div class="card"><span class="lab">VISITS</span><div class="scroll"><table><thead><tr><th>Date</th><th class="num">Best</th><th class="num">Gap</th><th>Setup</th><th class="num">Rating</th></tr></thead><tbody>'+(v.length?v.map(d=>{const g=gapOf(d);return '<tr><td><a href="#track" data-go="'+esc(d.id)+'">'+esc(nice(d.date))+'</a><div class="mut" style="font-size:12px">'+esc(d.cond||'')+'</div></td><td class="num">'+(bestOf(d)?fmtT(bestOf(d)):'')+'</td><td class="num">'+(g!=null?g.toFixed(1)+' s':'')+'</td><td>'+esc(setupSum(d.setup))+'</td><td class="num">'+esc(d.rating||'')+'</td></tr>'}).join(''):'<tr><td colspan="5" class="empty">No visits logged yet.</td></tr>')+'</tbody></table></div></div>'+gSessList(gsess(tk),'GPS LAP TIMING')+'</div><div><div class="card"><span class="lab">BASE SETUP · WHAT WORKS HERE</span><p class="mut" style="margin-top:0">Every visit starts from this. Update it from a track day with "Save as base setup".</p>'+setupForm(doc,'setup.')+'</div>'+satCard(tk)+'<div class="card"><span class="lab">TRACK NOTES</span><textarea data-doc="'+esc(doc)+'" data-k="notes" id="tnotes" rows="5" aria-label="Track notes" placeholder="Lines, where ruts form, gate pick, the start">'+esc(t.notes||'')+'</textarea></div></div></div>';
}
function renderTrackView(){return '<div class="seg"><a href="#track" data-sub="days" class="'+(S.sub!=='lib'&&S.sub!=='gps'?'on':'')+'">Track days</a><a href="#track" data-sub="lib" class="'+(S.sub==='lib'?'on':'')+'">Tracks</a><a href="#track" data-sub="gps" class="'+(S.sub==='gps'?'on':'')+'">Lap timing</a></div>'+(S.galign?(setTimeout(alDraw,0),renderAlign()):S.sub==='lib'?trackLib():S.sub==='gps'?renderTiming():trackDays())}

/* ---------- stats ---------- */
function lineChart(id,pts,unit){return '<div class="fig" id="'+id+'" data-pts="'+esc(JSON.stringify(pts))+'" data-u="'+esc(unit)+'"><svg></svg></div>'}
function drawCharts(){document.querySelectorAll('.fig[data-pts]').forEach(f=>{const s=f.querySelector('svg'),pts=JSON.parse(f.dataset.pts||'[]'),u=f.dataset.u;const W=s.clientWidth,H=s.clientHeight;if(!W)return;
  if(pts.length<2){s.innerHTML='<text x="4" y="24">Log at least 2 entries to see the trend.</text>';return}
  const ys=pts.map(p=>p[1]),lo=Math.min(...ys),hi=Math.max(...ys),pad=(hi-lo)*.15||1,y0=lo-pad,y1=hi+pad,x0=pts[0][0],x1=pts.at(-1)[0];
  const X=x=>40+(x-x0)/((x1-x0)||1)*(W-60),Y=y=>H-24-(y-y0)/(y1-y0)*(H-40);
  const d=pts.map((p,i)=>(i?'L':'M')+X(p[0]).toFixed(1)+' '+Y(p[1]).toFixed(1)).join('');
  const last=pts.at(-1),lab=v=>u==='s'?fmtT(v):(+v.toFixed(1)),c=f.dataset.c||getComputedStyle(document.documentElement).getPropertyValue('--acc').trim()||'#ffd60a';
  const cs=getComputedStyle(document.documentElement),gl=cs.getPropertyValue('--line').trim()||'#2a2e36',ik=cs.getPropertyValue('--ink').trim()||'#f3f4f6';
  s.innerHTML='<line x1="40" x2="'+(W-20)+'" y1="'+Y(lo)+'" y2="'+Y(lo)+'" stroke="'+gl+'"/><line x1="40" x2="'+(W-20)+'" y1="'+Y(hi)+'" y2="'+Y(hi)+'" stroke="'+gl+'"/><text x="0" y="'+(Y(hi)+4)+'">'+esc(lab(hi))+'</text><text x="0" y="'+(Y(lo)+4)+'">'+esc(lab(lo))+'</text><path d="'+d+'" fill="none" stroke="'+c+'" stroke-width="2.5" stroke-linejoin="round"/><circle cx="'+X(last[0])+'" cy="'+Y(last[1])+'" r="5" fill="'+c+'"/><text x="'+Math.min(X(last[0])+8,W-80)+'" y="'+(Y(last[1])-10)+'" style="fill:'+ik+';font-weight:700">'+esc(lab(last[1]))+(u==='s'?'':' '+esc(u))+'</text><text x="40" y="'+(H-4)+'">'+esc(nice(toS(x0)))+'</text><text x="'+(W-20)+'" y="'+(H-4)+'" text-anchor="end">'+esc(nice(toS(x1)))+'</text>';});}
function renderStats(){
  const sub=S.ssub||'progress';
  let body='';
  if(sub==='progress'){const days=Object.keys(S.days).sort();
    const wt=days.filter(d=>+S.days[d].weight>0).map(d=>[toN(d),+S.days[d].weight]);
    const rc=days.filter(d=>+getK(S.days[d],'whoop.rec')>0).slice(-42).map(d=>[toN(d),+S.days[d].whoop.rec]);
    const hv=days.filter(d=>+getK(S.days[d],'whoop.hrv')>0).slice(-42).map(d=>[toN(d),+S.days[d].whoop.hrv]);
    body='<div class="grid"><div><div class="card"><span class="lab">BODYWEIGHT · AIM DOWN 0.2–0.4 KG A WEEK UNTIL 24 JAN</span>'+lineChart('c1',wt,'kg')+'</div><div class="card"><span class="lab">WAIST · MONDAY MORNINGS</span>'+lineChart('c5',days.filter(d=>+S.days[d].waist>0).map(d=>[toN(d),+S.days[d].waist]),'cm')+'</div><div class="card"><span class="lab">RECOVERY · LAST 6 WEEKS</span><div class="fig" id="c2" data-c="#2ad67a" data-pts="'+esc(JSON.stringify(rc))+'" data-u="%"><svg></svg></div></div><div class="card"><span class="lab">HRV · LAST 6 WEEKS</span><div class="fig" id="c3" data-c="#93acd0" data-pts="'+esc(JSON.stringify(hv))+'" data-u="ms"><svg></svg></div></div></div><div><div class="card"><span class="lab">BENCHMARKS · RETEST JAN, JUN, OCT</span><div class="scroll"><table><thead><tr><th>Test</th><th>Wk 1</th><th>Jan</th><th>Jun</th><th>Oct</th></tr></thead><tbody>'+BM.map(b=>'<tr><td>'+esc(b[1])+'<div class="mut" style="font-size:12px">'+esc(b[2])+'</div></td>'+['wk1','jan','jun','oct'].map(p=>'<td>'+inp('profile/main','bench.'+b[0]+'.'+p,{lab:b[1]+' '+p})+'</td>').join('')+'</tr>').join('')+'</tbody></table></div></div></div></div>'}
  else if(sub==='coach'){const rv=Object.entries(S.reviews).filter(([k,r])=>r&&r.text).sort((a,b)=>String(b[1].date).localeCompare(String(a[1].date)));
    body='<div class="grid"><div><div class="card"><span class="lab">COACH REVIEWS</span>'+(rv.length?rv.map(([k,r])=>'<div class="ex"><div class="exh"><b>'+esc(r.title||'Review')+'</b><span class="mut">'+esc(r.date||'')+'</span></div><div class="note">'+esc(r.text)+'</div></div>').join(''):'<p class="empty">No reviews yet. Log a week, then ask for one.</p>')+'</div></div><div><div class="card"><span class="lab">GET A REVIEW</span><p style="margin-top:0">Message Claude: <b>"Review my last week"</b>. Claude reads everything logged here and writes the review into this tab.</p>'+(S.sample?'<button id="ask">Quick review: last 14 days</button>':'')+'<p id="askmsg" class="mut"></p></div></div></div>'}
  else body=profCard()+'<div class="card" style="max-width:760px"><span class="lab">LAYOUT</span><p style="margin:0 0 8px">'+(isFocus()?'<b>Focus</b> (recommended): up-next card, gym mode with rest timer, one-tap logging, sessions that adjust to your Whoop recovery.':'<b>Classic</b>: every session open on one page, everything logged by hand, no automatic changes.')+'</p><button id="lay">'+(isFocus()?'Switch to Classic layout':'Switch to Focus layout')+'</button></div>'+(!S.canInstall&&window.MXSB?'<div class="card" style="max-width:760px"><span class="lab">THIS APP</span><p style="margin:0 0 8px"><b>iPhone:</b> open it in Safari, tap Share, then Add to Home Screen. <b>Mac:</b> in Safari choose File, then Add to Dock. In Chrome use the install icon in the address bar. You get the orange icon and it opens full screen.</p><div class="row2" style="flex-wrap:wrap"><button id="mxupd">'+(S.updReady?'Update now':'Check for updates')+'</button><button class="ghost" id="signout">Sign out</button></div><p class="mut" style="font-size:12px;margin:8px 0 0">Version '+esc(mxVer())+(S.updMsg?' · '+esc(S.updMsg):'')+'</p></div>':'')+(S.canInstall?'<div class="card" style="max-width:760px"><span class="lab">DESKTOP APP</span><p style="margin:0 0 8px">Install this as an app on your Mac, with its own window and icon.</p><button id="install">Install on desktop</button></div>':'')+'<div class="card" style="max-width:760px"><span class="lab">TRAINING NUMBERS</span><p class="mut" style="margin-top:0">These set every weight and heart-rate target in the plan.</p><div class="fields">'+fld('profile/main','maxHR','Max heart rate (bpm)',{ph:'200'})+fld('profile/main','tests.ohp','Overhead press, best 5 (kg)')+fld('profile/main','tests.bench','DB bench, best 8, per hand (kg)')+'</div><p class="mut">Max HR: the highest number Polar or Whoop has recorded in a hard session. Until you set it, the plan uses 200. Do a hard set of 5 overhead press and 8 dumbbell bench in your first Strength D to fill the last two. Squat and trap-bar weights come from your week 1 benchmarks.</p></div>';
  return '<div class="seg">'+[['progress','Progress'],['coach','Coach'],['profile','Profile']].map(x=>'<a href="#stats" data-ss="'+x[0]+'" class="'+(sub===x[0]?'on':'')+'">'+x[1]+'</a>').join('')+'</div>'+body;
}
const BM=[['squat','Back squat, best set of 3 (kg)','+10% by Jan'],['trap','Trap-bar deadlift, best set of 3 (kg)','+10% by Jan'],['chin','Chin-ups in 10 min','Pro benchmark: 50'],['hang','Dead hang (s)','Higher is better'],['calf','Calf raises, weaker leg','Pro benchmark: 25'],['plank','Side plank, weaker side (s)','+50% by Jan'],['hlr','Hanging leg raises (reps)','+50% by Jan'],['row','2 km row (s)','Lower is better'],['hrdrop','HR drop 60 s after row (bpm)','+10 bpm by Jan'],['rhr','Resting HR, 7-day avg','Lower is better'],['bw','Bodyweight, weekly avg (kg)','Down 0.2–0.4 kg a week until '+nice(addD(D.p3s,-1)).slice(4)],['waist','Waist at belly button (cm)','Down 2–4 cm by late Jan'],['hotlap','Best hot lap, same track (s)','2 s faster by Round 1'],['sector','Corner sector best (s)','Lower is better'],['motobest','30 + 2 moto: best lap (s)','Lower is better'],['motogap','30 + 2 moto: last-2-laps gap (s)','Under 2 s']];



