const SWAP={air:'Use the Wattbike at the same heart rate.',row:'Use the SkiErg, damper 5, at the same heart rate.',tread:'Use the Wattbike at the same heart rate.',bike:'Use the rower at 18–22 strokes a minute, same heart rate.',road:'Ride the Wattbike indoors at the same heart rate.'};
const WHY={air:'Arms and legs together, closest to riding',row:'Whole body, steady output',tread:'Easy on the legs before jumps and deadlifts',bike:'Lowest impact',road:'Long and steady, easy on the joints'};
